#!/usr/bin/env python3
"""Generate the docs page from core's compiled canonical input defaults."""
import argparse,hashlib,json,pathlib
root=pathlib.Path(__file__).resolve().parents[1]
parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
source=root.parent/'core/config/input.default.json';data=source.read_bytes();config=json.loads(data)
lines=['---','title: Keymap','description: Hyprune keymap v2 defaults, generated from the core config.','---','','<!-- Generated by scripts/generate-keymap.py; edit core/config/input.default.json. -->',f'<!-- SHA256 {hashlib.sha256(data).hexdigest()} -->','','Hyprune owns `~/.config/hyprune/input.json`. Edit it directly or use the Director’s Settings tab. Core validates and live-reloads it independently of Hyprland. Each action accepts up to three bindings. `[L]` means hold for **'+str(config['longHoldMs'])+' ms** by default.','','Movement keys are listed **HJKL first**, then WASD and arrows. E uses a window or workspace wall in place. F zooms into that window or workspace. Super+Tab or the Back mouse button returns to world control. A colliding Hyprland shortcut is stolen only in the mode that defines it, while the world is active.','','Q holds scope zoom; the wheel changes its magnification. Shift snaps position-tool movement to 0.1 m, rotation to 15°, and scale factors to 0.1. Keys 1–4 select tools; 5 cycles the shell HUD concept and is rebindable as `hud.cycle`. The window tool cycles place/lock; the path tool cycles open/closed line/curve/arc; the position tool cycles move/rotate/scale.','']
order=['look','forward','back','left','right','menu','sprint','up','down','use','focus','noclip','scope','debug','capture','record.toggle','carry','resize','distance','rotate','tool1','tool2','tool3','tool4','hud.cycle','transport','autopilot','primary','secondary','wheel','fly','exit']
for mode,actions in config['modes'].items():
 lines+=['## '+{'world':'In-world','interactive':'Interactive / use in place','focus':'Focus / fullscreen','menu':'Menu'}[mode],'','| Action | Default bindings |','| --- | --- |']
 for action in order:
  if action in actions:lines.append('| '+action+' | '+(', '.join('`'+b.replace('|','\\|')+'`'for b in actions[action]) or 'Unbound')+' |')
 lines+=['']
lines+=['`record.toggle` starts/stops a private input/camera recording and is unbound by default. Application keystrokes are masked unless explicitly enabled through the recording API. IPC 0.12 Settings can rebind it without a Hyprland reload.','','## File options','','| Option | Default | Valid range / meaning |','| --- | --- | --- |','| version | '+str(config['version']).lower()+' | Exactly 2 |','| longHoldMs | '+str(config['longHoldMs']).lower()+' | 100–5000 ms |','| scopeVignette | '+str(config['scopeVignette']).lower()+' | Scope ring and shaded edges |','| invert_y | '+str(config['invert_y']).lower()+' | Reverse vertical mouse look; false means mouse up looks up |','| show_area_markers | '+str(config.get('show_area_markers',False)).lower()+' | Optional core-rendered area/place labels; active waypoint/route remain visible |','| useDistance | '+str(config['useDistance']).lower()+' | 0.2–30 m; E maximum distance |','| useTolerance | '+str(config['useTolerance']).lower()+' | 0–0.5 m margin around an aimed surface |','| captureInputLimit | '+str(config['captureInputLimit']).lower()+' | 16–1024 recent input events in captures |','| modes | tables above | All listed actions; 0–3 bindings each |','','Binding names use XKB keysyms, `Super+Shift+Ctrl+Alt+key`, `LMB`, `RMB`, `MMB`, `Back`, `Forward`, `ButtonN`, `Wheel`, `WheelUp`, `WheelDown`, or `MouseMove`. Keys use the active keyboard layout’s base-level symbol, with letters canonicalized to lowercase; Shift/Ctrl/Alt/Super are separate modifiers. Press identity is retained through release even if modifiers or layout change. Modifier order is canonicalized. F12 remains the emergency exit. Internal conflicts reject a save; Hyprland collisions are reported and accepted. Invalid edits retain the last valid configuration.','','U in world, or Super+U in interactive/focus/menu, writes a private timestamped JSON/PNG capture pair under `$XDG_STATE_HOME/hyprune/captures/` (default `~/.local/state/hyprune/captures/`) and shows the path in a notice. The JSON records the completed world frame camera, age and timings, plus mode, tools, surfaces, placements, recent IPC/events and the bounded input history.','','Compositor graphics, movement speed, sensitivity and inertia remain in `hl.plugin.hyprune.config({...})`; input bindings belong in the independent JSON file.','','Tools save paths, window locks and object transforms in `$XDG_STATE_HOME/hyprune/editor.json`, scoped by world and area. Authored world packages stay read-only.','']
output=root/'src/content/docs/keymap.md';text='\n'.join(lines)
if args.check:
 if not output.exists() or output.read_text()!=text:raise SystemExit('Keymap page is stale; run scripts/generate-keymap.py')
else:output.write_text(text)
